  for (let sourceIndex = 0; sourceIndex < sources.length; sourceIndex++) {
    const src = String(sources[sourceIndex]);
    const file = files[sourceIndex] || `<source ${sourceIndex + 1}>`;
    let line = 1;
    let lineComment = false;

    for (let i = 0; i < src.length; i++) {
      const ch = src[i];
